<?php
declare(strict_types=1);
namespace app\common\service\merchant;

use think\facade\Db;
use InvalidArgumentException as Invalid;
use app\common\service\merchant\clip\ClipCredentialVault as Vault;

final class MerchantPublishService
{
    public const PLATFORMS=['douyin'=>'抖音','kuaishou'=>'快手','xiaohongshu'=>'小红书'];
    public static function staff(int $t,int $u,array $p=[]):array{
        $q=MerchantFilmService::scope('oem_merchant_store_staff',$t,$u)->where('delete_time',0);if(($p['active']??false))$q->where('status',1);
        if(($p['store_id']??'')!=='')$q->where('store_id',MerchantFilmService::number($p['store_id']));$key=MerchantFilmService::text($p['keyword']??'',50);if($key!=='')$q->where(function($q)use($key){$q->whereLike('name','%'.addcslashes($key,'%_\\').'%')->whereOr('mobile','like','%'.addcslashes($key,'%_\\').'%');});
        $stores=MerchantFilmService::scope('oem_merchant_store',$t,$u)->where(['delete_time'=>0,'status'=>1])->column('name','id');$rows=$q->whereIn('store_id',array_keys($stores)?:[0])->order('id desc')->select()->toArray();
        $bindings=MerchantFilmService::scope('oem_staff_task_access',$t,$u)->column('subscribe','staff_id');foreach($rows as &$r){$r['store_name']=$stores[$r['store_id']];$r['wechat_bound']=(int)($bindings[$r['id']]??0)===1;}return ['lists'=>$rows,'stores'=>array_map(fn($id,$name)=>['id'=>$id,'name'=>$name],array_keys($stores),$stores),'platforms'=>self::PLATFORMS];
    }
    private static function task(int $t,int $u,int $id,bool $lock=false):array{$r=MerchantFilmService::scope('oem_publish_task',$t,$u)->where('id',$id)->lock($lock)->find();if(!$r)throw new Invalid('任务不存在或无访问权限');return $r;}
    private static function pool(int $t,int $u,int $folder,string $kind,int $store):array{
        if(!$folder)return [];$f=MerchantFilmService::scope('oem_material_folder',$t,$u)->where(['id'=>$folder,'delete_time'=>0])->whereIn('kind',$kind==='image_text'?['image_text','copy']:[$kind])->find();if(!$f)throw new Invalid('文案或话题库不存在或无访问权限');
        return Db::name('oem_merchant_material')->alias('m')->join('oem_material_meta mm','m.id=mm.material_id AND m.tenant_id=mm.tenant_id AND m.user_id=mm.user_id')->where(['m.tenant_id'=>$t,'m.user_id'=>$u,'m.kind'=>$f['kind'],'m.delete_time'=>0,'mm.folder_id'=>$folder])->whereIn('m.store_id',[0,$store])->where('m.content','<>','')->order('m.id')->limit(100)->column('m.content');
    }
    public static function create(int $t,int $u,array $p):array{
        $key=MerchantFilmService::text($p['request_key']??'',64,true);if(!preg_match('/^[A-Za-z0-9_-]{16,64}$/D',$key))throw new Invalid('提交标识不正确');$title=MerchantFilmService::text($p['title']??'',80,true);$content=MerchantFilmService::text($p['content']??'',500,true);
        $ids=$p['staff_ids']??[];if(!is_array($ids)||!array_is_list($ids)||!$ids||count($ids)>100)throw new Invalid('请选择1至100名员工');$ids=array_values(array_unique(array_map(fn($v)=>MerchantFilmService::number($v,1),$ids)));
        $platforms=$p['platforms']??[];if(!is_array($platforms)||!array_is_list($platforms)||!$platforms||count($platforms)>3||array_diff($platforms,array_keys(self::PLATFORMS)))throw new Invalid('请选择发布平台');$platforms=array_values(array_unique($platforms));$refs=MerchantFilmService::refs($p['refs']??[]);
        $due=MerchantFilmService::number($p['due_time']??0,0,time()+180*86400);$deadline=MerchantFilmService::number($p['deadline']??0,0,time()+365*86400);if($deadline&&$deadline<=max(time(),$due))throw new Invalid('截止时间须晚于发布时间');$copy=MerchantFilmService::text($p['copy_text']??'',10000);$topics=MerchantFilmService::text($p['topics']??'',1000);$cf=MerchantFilmService::number($p['copy_folder_id']??0);$tf=MerchantFilmService::number($p['topic_folder_id']??0);if($copy===''&&!$cf)throw new Invalid('请填写发布文案或选择文案库');
        $config=['staff_ids'=>$ids,'platforms'=>$platforms,'refs'=>$refs,'copy_text'=>$copy,'topics'=>$topics,'copy_folder_id'=>$cf,'topic_folder_id'=>$tf,'due_time'=>$due,'deadline'=>$deadline];$json=json_encode($config,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);
        return Db::transaction(function()use($t,$u,$key,$title,$content,$config,$json,$due,$deadline,$ids,$platforms,$refs,$copy,$topics,$cf,$tf){
            MerchantFilmService::scope('oem_merchant',$t,$u)->lock(true)->find();$old=MerchantFilmService::scope('oem_publish_task',$t,$u)->where('request_key',$key)->find();if($old){if($old['config_json']!==$json||$old['title']!==$title||$old['content']!==$content)throw new Invalid('提交标识已用于其他任务');return ['id'=>(int)$old['id'],'duplicate'=>true];}
            $staff=array_column(self::staff($t,$u,['active'=>true])['lists'],null,'id');foreach($ids as $id)if(!isset($staff[$id]))throw new Invalid('员工或所属门店已停用、回收或无访问权限');foreach($refs as $ref)MerchantFilmService::asset($t,$u,$ref);
            $copyUsage=MerchantFinishedCatalogService::usage($t,$u)['image_text'];$copyLimit=$cf?MerchantFinishedCatalogService::copyLimit($t,$u,$cf):0;$prepared=[];foreach($ids as $index=>$id){$row=$staff[$id];$copies=self::pool($t,$u,$cf,'image_text',(int)$row['store_id']);$tags=self::pool($t,$u,$tf,'topic',(int)$row['store_id']);if($cf&&!$copies)throw new Invalid('所选文案库没有适用于该门店的文案');if($tf&&!$tags)throw new Invalid('所选话题库没有适用于该门店的话题');if($cf&&$copyLimit){$copies=array_values(array_filter($copies,fn($text)=>($copyUsage[MerchantFinishedCatalogService::copyKey($cf,$text)]??0)+count($platforms)<=$copyLimit));if(!$copies)throw new Invalid('所选图文库没有适用于该门店且有剩余使用次数的内容');$keyCopy=MerchantFinishedCatalogService::copyKey($cf,$copies[$index%count($copies)]);$copyUsage[$keyCopy]=($copyUsage[$keyCopy]??0)+count($platforms);}$prepared[$id]=['asset_ref'=>$refs[$index%count($refs)],'copy_text'=>$cf?$copies[$index%count($copies)]:$copy,'topics'=>$tf?mb_substr(implode(' ',array_slice($tags,0,10)),0,1000):$topics];}
            MerchantFinishedCatalogService::assertCapacity($t,$u,$prepared,count($platforms),$cf);
            $id=(int)Db::name('oem_publish_task')->insertGetId(['tenant_id'=>$t,'user_id'=>$u,'request_key'=>$key,'title'=>$title,'content'=>$content,'config_json'=>$json,'due_time'=>$due?:time(),'deadline'=>$deadline,'create_time'=>time()]);
            foreach($ids as $staffId){foreach($platforms as $platform)Db::name('oem_publish_assignment')->insert(['tenant_id'=>$t,'user_id'=>$u,'task_id'=>$id,'staff_id'=>$staffId,'store_id'=>$staff[$staffId]['store_id'],'platform'=>$platform]+$prepared[$staffId]);Db::name('oem_task_notification')->insert(['tenant_id'=>$t,'user_id'=>$u,'task_id'=>$id,'staff_id'=>$staffId,'due_time'=>$due?:time(),'create_time'=>time(),'update_time'=>time()]);}
            return ['id'=>$id,'assignments'=>count($ids)*count($platforms),'notice'=>'任务已保存，按发布时间进入员工任务页；微信发送结果请查看通知状态。'];
        });
    }
    public static function listing(int $t,int $u,array $p):array{
        $q=MerchantFilmService::scope('oem_publish_task',$t,$u);if(isset($p['library_id'])&&$p['library_id']!==''){$library=MerchantFilmService::number($p['library_id']);MerchantFilmService::library($t,$u,$library);$refs=MerchantFilmService::scope('oem_film_entry',$t,$u)->where('library_id',$library)->column('asset_ref');$tasks=MerchantFilmService::scope('oem_publish_assignment',$t,$u)->whereIn('asset_ref',$refs?:[''])->column('task_id');$q->whereIn('id',$tasks?:[0]);}$key=MerchantFilmService::text($p['keyword']??'',80);if($key!=='')$q->whereLike('title','%'.addcslashes($key,'%_\\').'%');$count=(clone $q)->count();$page=max(1,(int)($p['page']??1));$rows=$q->order('id desc')->page($page,20)->select()->toArray();foreach($rows as &$r){unset($r['config_json']);$r['total']=MerchantFilmService::scope('oem_publish_assignment',$t,$u)->where('task_id',$r['id'])->count();$r['completed']=MerchantFilmService::scope('oem_publish_assignment',$t,$u)->where(['task_id'=>$r['id'],'state'=>'completed'])->count();$r['scheduled']=$r['state']==='active'&&$r['due_time']>time();$r['expired']=$r['state']==='active'&&$r['deadline']>0&&$r['deadline']<=time();}return ['lists'=>$rows,'count'=>$count,'page'=>$page];
    }
    public static function detail(int $t,int $u,array $p):array{
        $task=self::task($t,$u,MerchantFilmService::number($p['id']??0,1));$task['config']=json_decode($task['config_json'],true);unset($task['config_json']);$q=MerchantFilmService::scope('oem_publish_assignment',$t,$u)->where('task_id',$task['id']);if(($p['platform']??'')!=='')$q->where('platform',$p['platform']);$rows=$q->order('id')->select()->toArray();$staff=MerchantFilmService::scope('oem_merchant_store_staff',$t,$u)->column('name','id');$stores=MerchantFilmService::scope('oem_merchant_store',$t,$u)->column('name','id');foreach($rows as &$r){$r['staff_name']=$staff[$r['staff_id']]??'已移除员工';$r['store_name']=$stores[$r['store_id']]??'已移除门店';}return ['task'=>$task,'lists'=>$rows,'notifications'=>MerchantFilmService::scope('oem_task_notification',$t,$u)->where('task_id',$task['id'])->order('id')->select()->toArray()];
    }
    public static function cancel(int $t,int $u,array $p):void{Db::transaction(function()use($t,$u,$p){$r=self::task($t,$u,MerchantFilmService::number($p['id']??0,1),true);MerchantFilmService::scope('oem_publish_task',$t,$u)->where('id',$r['id'])->update(['state'=>'cancelled','cancel_time'=>time()]);MerchantFilmService::scope('oem_task_notification',$t,$u)->where('task_id',$r['id'])->whereIn('state',['queued','blocked','failed'])->update(['state'=>'cancelled','update_time'=>time()]);});}
    public static function review(int $t,int $u,array $p):void{Db::transaction(function()use($t,$u,$p){$id=MerchantFilmService::number($p['id']??0,1);$row=MerchantFilmService::scope('oem_publish_assignment',$t,$u)->where('id',$id)->lock(true)->find();if(!$row||$row['state']!=='submitted')throw new Invalid('记录不存在或不处于待审核状态');$task=self::task($t,$u,(int)$row['task_id'],true);if($task['state']!=='active')throw new Invalid('任务已取消');$decision=$p['decision']??'';if(!in_array($decision,['approved','rejected'],true))throw new Invalid('审核结果不正确');$note=MerchantFilmService::text($p['note']??'',500,$decision==='rejected');MerchantFilmService::scope('oem_publish_assignment',$t,$u)->where('id',$id)->update(['state'=>$decision==='approved'?'completed':'rejected','note'=>$note,'review_time'=>time()]);});}
    public static function invite(int $t,int $u,array $p):array{
        $id=MerchantFilmService::number($p['staff_id']??0,1);$staff=array_column(self::staff($t,$u,['active'=>true])['lists'],null,'id');if(!isset($staff[$id]))throw new Invalid('员工不可用');
        return Db::transaction(function()use($t,$u,$p,$id){MerchantFilmService::scope('oem_merchant_store_staff',$t,$u)->where('id',$id)->lock(true)->find();$row=MerchantFilmService::scope('oem_staff_task_access',$t,$u)->where('staff_id',$id)->find();if(!$row||($p['rotate']??'')==='1'){$token=bin2hex(random_bytes(32));$data=['token_hash'=>hash('sha256',$token),'token_cipher'=>Vault::seal(['token'=>$token],$t,'task_invite'),'appid'=>'','openid_cipher'=>'','subscribe'=>0,'update_time'=>time()];if($row){Db::name('oem_task_oauth_state')->where('access_id',$row['id'])->delete();MerchantFilmService::scope('oem_staff_task_access',$t,$u)->where('id',$row['id'])->update($data);}else Db::name('oem_staff_task_access')->insert($data+['tenant_id'=>$t,'user_id'=>$u,'staff_id'=>$id,'create_time'=>time()]);}else $token=Vault::open($row['token_cipher'],$t,'task_invite')['token'];return ['path'=>'/employee/tasks#'.$token,'notice'=>'专属员工链接，仅提供给对应员工；重置后旧链接和绑定失效。'];});
    }
    public static function access(string $token):array{
        if(!preg_match('/^[a-f0-9]{64}$/D',$token))throw new Invalid('员工链接无效');$row=Db::name('oem_staff_task_access')->where('token_hash',hash('sha256',$token))->find();if(!$row)throw new Invalid('员工链接已失效');$t=(int)$row['tenant_id'];$u=(int)$row['user_id'];$valid=array_column(self::staff($t,$u,['active'=>true])['lists'],null,'id');if(!isset($valid[$row['staff_id']]))throw new Invalid('员工或门店已停用');$merchant=MerchantFilmService::scope('oem_merchant',$t,$u)->where('status',1)->find();$owner=Db::name(MerchantAccountTables::name($t,'user'))->where(['tenant_id'=>$t,'id'=>$u,'is_disable'=>0])->whereNull('delete_time')->find();if(!$merchant||!$owner||\app\common\service\app\AppAccessService::assertTenantCanUse($t,'merchant_marketing',$u))throw new Invalid('商家服务不可用');return $row+['staff'=>$valid[$row['staff_id']]];
    }
    public static function portal(array $access):array{
        $t=(int)$access['tenant_id'];$u=(int)$access['user_id'];$tasks=MerchantFilmService::scope('oem_publish_task',$t,$u)->where('state','active')->where('due_time','<=',time())->where(function($q){$q->where('deadline',0)->whereOr('deadline','>',time());})->column('id');$rows=MerchantFilmService::scope('oem_publish_assignment',$t,$u)->where('staff_id',$access['staff_id'])->whereIn('task_id',$tasks?:[0])->order('id desc')->select()->toArray();
        foreach($rows as &$r){$task=self::task($t,$u,(int)$r['task_id']);$r=array_intersect_key($r,array_flip(['id','task_id','platform','asset_ref','copy_text','topics','state','proof_url','note','submit_time']));$r+=['title'=>$task['title'],'content'=>$task['content'],'deadline'=>$task['deadline']];try{$a=MerchantFilmService::asset($t,$u,$r['asset_ref']);$r['video_title']=$a['title'];$r['available']=true;}catch(Invalid){$r['available']=false;}}
        return ['staff_name'=>$access['staff']['name'],'store_name'=>$access['staff']['store_name'],'bound'=>(bool)$access['subscribe'],'lists'=>$rows];
    }
    public static function employeeAction(array $access,array $p):array{
        $t=(int)$access['tenant_id'];$u=(int)$access['user_id'];$id=MerchantFilmService::number($p['id']??0,1);return Db::transaction(function()use($access,$p,$t,$u,$id){$row=MerchantFilmService::scope('oem_publish_assignment',$t,$u)->where(['id'=>$id,'staff_id'=>$access['staff_id']])->lock(true)->find();if(!$row)throw new Invalid('任务不存在');$task=self::task($t,$u,(int)$row['task_id'],true);if($task['state']!=='active'||$task['due_time']>time()||($task['deadline']&&$task['deadline']<=time()))throw new Invalid('任务尚未生效、已截止或已取消');MerchantFilmService::asset($t,$u,$row['asset_ref']);$op=$p['action']??'';
            if($op==='delivery')return MerchantFilmService::delivery($t,$u,$row['asset_ref']);
            if($op==='claim'&&$row['state']==='pending')MerchantFilmService::scope('oem_publish_assignment',$t,$u)->where('id',$id)->update(['state'=>'claimed','claim_time'=>time()]);
            elseif($op==='submit'&&in_array($row['state'],['claimed','rejected'],true)){$url=MerchantFilmService::text($p['proof_url']??'',2048,true);if(!filter_var($url,FILTER_VALIDATE_URL)||parse_url($url,PHP_URL_SCHEME)!=='https'||parse_url($url,PHP_URL_USER)!==null||parse_url($url,PHP_URL_PASS)!==null)throw new Invalid('请填写有效的HTTPS发布作品链接');MerchantFilmService::scope('oem_publish_assignment',$t,$u)->where('id',$id)->update(['state'=>'submitted','proof_url'=>$url,'submit_time'=>time(),'review_time'=>0,'note'=>'']);}
            elseif(!($op==='claim'&&$row['state']==='claimed'))throw new Invalid('任务状态不允许此操作');return [];
        });
    }
}
